\label{thm-varmain}
    For a very general hypersurface $D\subseteq {{\mathbb P}}^n$ of degree $d=2n$, there is some proper exceptional locus $S\subsetneq {{\mathbb P}}^n$ such that for every map $f: C\to {{\mathbb P}}^n$ from a smooth projective curve $C$ that is birational onto its image and $f(C)\not\subset D\cup S$, we have: \begin{itemize}
        \item for $n \geq 3$ \begin{equation}\label{eqn-logah3}
        2g(C)-2+|f^{-1}(D)|\geq \deg f^* L
    \end{equation}
    \item for $n=2$, \begin{equation}\label{eqn-logah2}
        2g(C)-2+|f^{-1}(D)| \geq \frac{1}{2} \deg f^*L
    \end{equation}
    \end{itemize}
    where $L = {\mathcal O}_{{{\mathbb P}}^n}(1)$ is the hyperplane bundle of ${{\mathbb P}}^n$.
    In the case $n=2$, $S\subsetneq {{\mathbb P}}^2$ is exactly the union of the bitangent and flex lines to $D$.

\label{prop-algGGLfordominantFamiliesOfCurves}
    Let $X$ be a smooth variety and $D$ be a smooth divisor in $X$ and $f: C \to X$ be the general element of a family of curves with fixed genus $g$ and number of intersection points $i$ with $D$, such that the family of curves dominates $X$. Then 
    \[ 2g-2 + i \geq (K_X+D) \cdot f(C) .\]

\label{thm-associatedLine}
    Let $D \subset {{\mathbb P}}^n$ be a very general hypersurface of degree $d=2n$. Then for any curve $C$ in ${{\mathbb P}}^n$ not contained in $D$, we have either \begin{enumerate}
        \item $C$ satisfies one of the following conditions \begin{eqnarray*}                  
        2g(C)-2+i(C,D)\geq \deg C \text{ and $n \geq 3$}  \\
        2g(C)-2+i(C,D)\geq \frac{1}{2} \deg C \text{ and $n = 2$}
    \end{eqnarray*}
    or
    \item $C$ lifts to $V$ and is contained in either a fiber or the undefined locus of the rational map $\theta: V \dashrightarrow \overline{U}_{0,d}^{\mathop{\mathrm{Sym}}\nolimits}$.
    \end{enumerate}

Let $X$ be a smooth projective variety and $D$ a smooth divisor in $X$. For $Y$ a smooth curve mapping via $f$ to $X$, we have that the degree of $N_{Y/X}(\log D)$ is equal to $2g(Y)-2+|f^{-1}(D)|-(K_X+D) \cdot Y$. In particular, for $X= {{\mathbb P}}^n$, $D = D_b$, $i = |f^{-1}(D)|$ and $Y=Y_b$ as above, we have
\begin{equation}\label{eqn-degree}
\begin{aligned}
\deg N_{Y_b/{{\mathbb P}}^n}(\log D_b) &=2g-2+i-(K_X + D)f_* Y_b\\
&=2g-2+i-(d-(n+1))e.
\end{aligned}
\end{equation}

We have the following sequences:
\begin{equation}\label{eqn-logtangent1}
\begin{tikzcd}
0 \ar{r} & T_{X}(-\log D)\ar{r} & T_{X} \ar{r} & {\mathcal O}_{D}(D)\ar{r} & 0
\end{tikzcd}
\end{equation}
\begin{equation}\label{eqn-logtangent2}
\begin{tikzcd}
0 \ar{r} & T_{Y}(-\log D)\ar{r} & T_{Y} \ar{r} & {\mathcal O}_{f^{-1}(D)}(f^{-1}(D))\ar{r} & 0
\end{tikzcd}
\end{equation}
\begin{equation}\label{eqn-lognormal}
\begin{tikzcd}[column sep=small]
0 \ar{r} & T_{Y}(-\log D)\ar{r} & f^*T_{X}(-\log D) \ar{r} & N_{Y/X}(\log D)\ar{r} & 0
\end{tikzcd}
\end{equation}

Taking degrees in (\ref{eqn-lognormal}), we get
\begin{equation}                    
\deg N_{Y/X}(\log D)=2g-2+i-(K_X + D)f_* Y.
\end{equation}

Recall that $T_{\mathcal Y}(-\log {\mathcal D})$ and $T_{\mathcal X}(-\log {\mathcal D})$ are vector bundles. By generic flatness, the restriction of (\ref{eqn-lognormalfam}) to the general fiber $Y_b$ remains exact. Hence, we have the short exact sequence
	\begin{equation*}
		0 \rightarrow \iota_b^*T_{\mathcal Y}(-\log {\mathcal D})\rightarrow \iota_b^*f^*T_{\mathcal X}(-\log {\mathcal D}) \rightarrow \iota_b^*N_{{\mathcal Y}/{\mathcal X}}(\log {\mathcal D})\rightarrow 0,
	\end{equation*}
	which together with (\ref{eqn-lognormal}) extend to the exact diagram:
	\begin{equation*}
		\begin{tikzcd}[column sep=18pt]
		& &0 &0 \\
		& &{\mathcal O}_{Y_b}^N \arrow[u] \arrow[r,equal] &{\mathcal O}_{Y_b}^N \arrow[u] \\
		&0 \arrow[r] &\iota_b^*T_{\mathcal Y}(-\log {\mathcal D}) \arrow[u] \arrow[r] &\iota_b^*f^*T_{\mathcal X}(-\log {\mathcal D}) \arrow[u] \arrow[r] &\iota_b^*N_{{\mathcal Y}/{\mathcal X}}(\log {\mathcal D}) \arrow[r] &0\\
		&0 \arrow[r] &T_{Y_b}(-\log D_b) \arrow[u] \arrow[r] &f_b^*T_{{{\mathbb P}}^n}(-\log D_b) \arrow[u] \arrow[r] &N_{Y_b/{{\mathbb P}}^n}(\log D_b) \arrow[r] \arrow[u, "\simeq"] &0\\		
		& &0 \arrow[u] &0 \arrow[u] & &
		\end{tikzcd}
	\end{equation*}
	Note that $N=\dim B$, and that the columns come from $Y_b$ and $D_b$ being fibers of the fibrations ${\mathcal Y}$ and ${\mathcal D}$, respectively. Therefore, the required isomorphism follows from applying the Nine Lemma to this diagram.

\label{prop-secdom}
	For some integer $s>0$, there is a surjection 
	\begin{equation*}
	M_1^{\oplus s} \longrightarrow M_d
	\end{equation*} 
	given by multiplication by generic polynomials of degree $d-1.$

\label{prop-bounds}
	Let $b\in B$ be a generic element, and let $N$ be a sheaf on the curve $Y_b$. Suppose that there is a generically surjective map
	\begin{equation*}
	\beta:f_b^*p_1^*M_1^{\oplus t}\longrightarrow N
	\end{equation*} for some $t$. Then, 
	\begin{equation}\label{eqn-bounds1}
	\deg N\geq -te.
	\end{equation}
	In particular, setting $N=\iota_b^*\text{Im} \;\alpha,$ we obtain
	\begin{equation}\label{eqn-bounds2}
	2g-2+i\geq (d-(n+1+t))e.
	\end{equation}

Since $\beta$ is generically surjective and $M_1$ injects into a direct sum of trivial sheaves, we have
	\begin{equation*}
	\deg N \geq \deg \beta\left(f_b^*p_1^*M_1^{\oplus t}\right)
	\geq t\cdot \deg f_b^*p_1^*M_1=-te.
	\end{equation*} If $N=\iota_b^*\text{Im} \;\alpha$, then by (\ref{eqn-degree}) and (\ref{eqn-cokerdegree}), we obtain
	\begin{align*}
	2g-2 +i &= (K_X + D_b)\cdot f_* Y_b + \deg N_{Y_b/{{\mathbb P}}^n}(\log D_b)\\
	&\geq (d-(n+1))e - te.
	\end{align*}

By Proposition \ref{prop-secdom}, there is a surjection $M_1^{\oplus s}\rightarrow M_d$ for some $s$. We can pull back this surjection via $f_b^*p_1^*$, and then compose with the surjection $\alpha_b$ from diagram (\ref{diag-4}) to get a generically surjective map
    \begin{equation*}
    	f_b^*p_1^*M_1^{\oplus t}\rightarrow \iota_b^*\text{Im }\alpha
    \end{equation*}
    for some $t\leq s$. Since $\alpha$ is not generically surjective, we must have \linebreak rank $\iota_b^*\text{Im }\alpha<$ rank $N_{Y_b/{{\mathbb P}}^n}(\log D_b) = n-1$, so we can take $t\leq n-2$. Proposition \ref{prop-bounds} then implies that $\deg \iota_b^*\text{Im }\alpha\geq -(n-2)e.$ Hence by (\ref{eqn-cokerdegree}), we have $\deg N_{Y_b/{{\mathbb P}}^n}(\log D_b)\geq-(n-2)e$, and so $$2g-2+i\geq (d-(2n-1))e.$$

\label{lem-2.10}
Suppose that rank $m_1=1$. Then, there exists a unique line $\ell:=\ell(p,b)\subseteq X_b={{\mathbb P}}^n$ through $p$ whose ideal $H^0({\mathcal O}_{{{\mathbb P}}^n}(d)\otimes I_\ell)$ is contained in $\ker \alpha\vert_{(p,b)}$, except possibly when $n=2$ and the curve $f_b:Y_b\rightarrow X_b={{\mathbb P}}^2$ satisfies 
\begin{equation}\label{eqn-hn}
    2g-2+i\geq \frac{1}{2}e.
\end{equation}

When such a line $\ell(p,b)$ exists, we call it the \emph{associated line} for $(p,b)$.

The first statement follows from the Grauert-Mulich Theorem, see for instance Theorem 2.1.4 of \cite{OkonekSchneiderSpindler} or \cite{PatelRiedlTseng} for more details. To see the second statement, consider the locus $W$ in ${{\mathbb P}}^2 \times H^0({{\mathbb P}}^2,{\mathcal O}_{{{\mathbb P}}^2}(4))$ of pairs $(\ell, f)$ such that $T_{{{\mathbb P}}^2}(-\log V(f))|_\ell \cong {\mathcal O}(1) \oplus {\mathcal O}(-2)$. We claim that $W$ has codimension 2, from which it follows that the projection of $W$ onto $H^0({{\mathbb P}}^2, {\mathcal O}_{{{\mathbb P}}^2}(4))$ has finite (or possibly empty) general fiber.

To show this, we consider a line $\ell$ in ${{\mathbb P}}^2$ and argue that the space of $f$ such that $T_{{{\mathbb P}}^2}(-\log V(f))|_\ell \cong {\mathcal O}(1) \oplus {\mathcal O}(-2)$ has codimension 2 in $H^0({{\mathbb P}}^2,{\mathcal O}_{{{\mathbb P}}^2}(4))$. This will not depend on the choice of coordinates, so assume that $\ell$ is the line $V(x)$. Consider the following diagram.
\begin{equation*}
	\begin{tikzcd}
		& & &0\arrow[d] &0\arrow[d] \\
		& & & {\mathcal O}_\ell \arrow[d] \arrow[r] & {\mathcal O}_\ell  \arrow[d] \\
		&0 \arrow[r] & T_{{{\mathbb P}}^2}(-\log D)|_\ell \arrow[d, "\simeq"] \arrow[r] & {\mathcal O}_{\ell}(1)^3 \arrow[d] \arrow[r, "\alpha"] & {\mathcal O}_{\ell}(4) \arrow[r] \arrow[d] &0 \\
		&0 \arrow[r] & T_{{{\mathbb P}}^2}(-\log D)|_\ell \arrow[r] & T_{{{\mathbb P}}^2}|_{\ell} \arrow[d] \arrow[r] & {\mathcal O}_{D \cap \ell}(D) \arrow[d] \arrow[r] &0\\	
		& & & 0 &0 
	\end{tikzcd}
\end{equation*}

Here, $\alpha$ is the map of partial derivatives $(f_x, f_y, f_z)$ restricted to $\ell$. For $T_{{{\mathbb P}}^2}(-\log D)|_\ell$ to have an ${\mathcal O}(1)$ summand, we see that some linear combination of the partials must be 0. Write $f$ as $f = x g(x,y,z) + h(y,z)$. Then the coordinates of the map $(f_x, f_y, f_z)$ restricted to $\ell$ will be $(g, h_y, h_z)$. There is a 2-dimensional choice for which linear combination $af_x+bf_y+cf_z$ is 0 (because the vanishing is invariant under scaling), and so it remains to show that a fixed linear combination, the codimension of $f$ such that $af_x+bf_y+cf_z$ vanishes upon restricting to $\ell$ is 4. If $b = c= 0$, we see that this is equivalent to the vanishing of $g|_{\ell}$, which is indeed four conditions: the vanishing of the $xy^3, xy^2z, xyz^2$ and $xz^3$ terms. If one of $b$ and $c$ is nonzero, we can select our coordinate $y$ so that $f_y$ is zero. This implies that $h_y$ is zero, which implies the vanishing of the $y^4, y^3z, y^2z^2$, and $yz^3$ terms, which is again four conditions. The result follows.

\label{lem-fixedModulus}
	Suppose that $d=2n$, and that the associated line is defined at a general point $(p,b) \in {\mathcal Y}$.
	Then, the map $\rho:{\mathcal Y} \dashrightarrow \overline{U}_{0,d}^{\mathop{\mathrm{Sym}}\nolimits}$ is constant.

\label{LANGLOGAH2LEMFIXMODULI}
Given a smooth quartic curve $D\subset {{\mathbb P}}^2$, let $C$ be an integral curve in ${{\mathbb G}}(1,2) = ({{\mathbb P}}^2)^\vee$ such that the rational map $\gamma: {{\mathbb G}}(1,2)\dashrightarrow M_{0,4}^{\mathop{\mathrm{Sym}}\nolimits}$ sending $L\in {{\mathbb G}}(1,2)$ to $L\cap D$ is constant at general points of $C$. Let $j$ be the $j$-invariant of the image $\gamma(C)$.
Then for $D$ general we have the following:
\begin{itemize}
\item $C$ passes through the $24$ flex lines to $D$;
\item if $j = j(2)$, then $C$ is a curve of degree $6$;
\item if $j = j(-e^{2\pi i/3})$, then $C$ is a curve of degree $4$;
\item if $j\ne j(2), j(-e^{2\pi i/3})$, then $C$ is a curve of degree $12$ with $24$ cusps at the $24$ flex lines; in addition, for $j$ general, $C$ is smooth outside of the $24$ cusps;
\item for each $j$, there exists a unique integral curve $C$ whose image $\gamma(C)$ is a point with $j$-invariant $j$;
\item two such curves $C_1$ and $C_2$ meet only at flex lines $L$ to $D$ with multiplicities
$$
(C_1. C_2)_{L} = \frac{1}{24} (C_1 . C_2).
$$
\end{itemize}
